   267→func TestHighlightCodeMatches(t *testing.T) {
   268→	t.Parallel()
   269→
   270→	styles := statusStyles{colorEnabled: true}
   271→
   272→	out := highlightCodeMatches("func HandleRequest(w)", "handlerequest", styles, false)
   273→	if !strings.Contains(out, "\x1b[") {
   274→		t.Errorf("expected ANSI codes in highlighted output, got %q", out)
   275→	}
   276→	if !strings.HasPrefix(out, "func ") || !strings.HasSuffix(out, "(w)") {
   277→		t.Errorf("expected unmatched text preserved around highlight, got %q", out)
   278→	}
   279→
   280→	if out := highlightCodeMatches("no match here", "zzz", styles, false); out != "no match here" {
   281→		t.Errorf("expected unchanged line when no match, got %q", out)
   282→	}
   283→
   284→	// Case-sensitive search must not highlight case variants.
   285→	if out := highlightCodeMatches("func HandleRequest(w)", "handlerequest", styles, true); out != "func HandleRequest(w)" {
   286→		t.Errorf("expected no highlight for case mismatch with caseSensitive, got %q", out)
   287→	}
   288→
   289→	// Non-ASCII input falls back to exact matching (no case folding).
   290→	if out := highlightCodeMatches("comment ÉTÉ ici", "été", styles, false); out != "comment ÉTÉ ici" {
   291→		t.Errorf("expected no case-folded highlight for non-ASCII input, got %q", out)
   292→	}
   293→	if out := highlightCodeMatches("comment été ici", "été", styles, false); !strings.Contains(out, "\x1b[") {
   294→		t.Errorf("expected exact non-ASCII match highlighted, got %q", out)
   295→	}
   296→
   297→	plain := statusStyles{colorEnabled: false}
   298→	if out := highlightCodeMatches("func main()", "main", plain, false); out != "func main()" {
   299→		t.Errorf("expected unchanged line when color disabled, got %q", out)
   300→	}
   301→}
